from typing import List

class Solution:
    def generateParenthesis(self, n: int) -> List[str]:
        result = []

        def valid(s: str) -> bool:
            balance = 0
            for ch in s:
                balance += 1 if ch == "(" else -1
                if balance < 0:
                    return False
            return balance == 0

        def dfs(s: str) -> None:
            if len(s) == 2 * n:
                if valid(s):
                    result.append(s)
                return
            dfs(s + "(")
            dfs(s + ")")

        dfs("")
        return result

