from typing import List

class Solution:
    def generateParenthesis(self, n: int) -> List[str]:
        result = []
        chars = [""] * (2 * n)

        def dfs(pos: int, left: int, right: int) -> None:
            if pos == 2 * n:
                result.append("".join(chars))
                return
            if left > 0:
                chars[pos] = "("
                dfs(pos + 1, left - 1, right)
            if right > left:
                chars[pos] = ")"
                dfs(pos + 1, left, right - 1)

        dfs(0, n, n)
        return result

